from pathlib import Path
import json, base64, html
from urllib.parse import quote

root = Path(__file__).resolve().parents[1]
site = root / 'site'
site.mkdir(exist_ok=True)
schools = json.loads((root / 'data' / 'applications-2026.json').read_text(encoding='utf-8'))
schools.sort(key=lambda s:s['name'])
address_records = [
    {
        key: value
        for key, value in school.items()
        if key not in ('classes', 'assignments', 'source', 'status')
    }
    for school in schools
]
(root / 'data' / 'schools-and-addresses.json').write_text(
    json.dumps(address_records, ensure_ascii=False, indent=2) + '\n', encoding='utf-8'
)
fallback_cards=''.join(
    f'<article class="card"><h3>{html.escape(s["name"])}</h3><p><strong>Endereço:</strong> {html.escape(s["address"])} — {html.escape(s["region"])}, São Cristóvão — SE.</p><p><a href="https://www.google.com/maps/dir/?api=1&amp;destination={quote(s.get("map_query") or ((s.get("previous_name") or s["full"])+", "+s["address"]+", São Cristóvão, Sergipe"),safe="")}" target="_blank" rel="noopener">Como chegar ↗</a></p></article>'
    for s in schools if s.get('address')
)
fallback='<noscript><p class="note">JavaScript está desativado. Consulte a lista de endereços abaixo.</p><div class="school-list">'+fallback_cards+'</div></noscript>'
logo=base64.b64encode((root/'assets'/'saese-logo.jpeg').read_bytes()).decode()
art=base64.b64encode((root/'assets'/'sao-cristovao-illustration.jpeg').read_bytes()).decode()
